import React, { forwardRef, useId } from "react";
import clsx from "clsx";
import { Checkbox as CheckboxStyles } from "@airbus/styles";
import { createUseStyles } from "../../lib/styling";
import { CommonProps } from "../helperTypes";

type Props = {
  /** If `true`, the component is checked */
  checked?: boolean;
  /** The default checked status for an uncontrolled component */
  defaultChecked?: boolean;
  /**
   * The id that will be passed to the underlying input element.
   */
  id?: string;
  /** Indicates that checkbox is in indeterminate state */
  indeterminate?: boolean;
  /** The label to show next to the `<input />` */
  label?: string;
  /**
   * props will be spread in internal label element
   * @default {}
   */
  labelProps?: {};
  /** The callback for when the input's state changes */
  onChange?: (
    event: React.ChangeEvent<HTMLInputElement>,
    checked: boolean
  ) => void;
  /** mouse click handler */
  onClick?: React.MouseEventHandler<HTMLInputElement>;
  /**
   * The size of the checkbox
   * @default medium
   */
  size?: "medium" | "large";
  /**
   * props passed to root component of checkbox (ie) div
   * @default {}
   */
  rootProps?: {};
};

export type CheckboxProps = Props & CommonProps;

const useStyles = createUseStyles(CheckboxStyles, "checkbox");

export const Checkbox = (
  props: CheckboxProps,
  ref: React.Ref<HTMLInputElement>
) => {
  const {
    id: propsId,
    label,
    size,
    indeterminate,
    className,
    onChange,
    labelProps = {},
    style,
    rootProps = {},
    ...rest
  } = props;
  const defaultId = `checkbox-${useId()}`;
  const id = propsId || defaultId;
  const classes = useStyles();

  const handleChange = (evt: React.ChangeEvent<HTMLInputElement>) => {
    onChange && onChange(evt, evt.target.checked);
  };

  return (
    <div
      className={clsx(
        className,
        classes.root,
        indeterminate && classes._indeterminate,
        size && classes[`_${size}`]
      )}
      style={style}
      onClick={(evt) => evt.stopPropagation()}
      {...rootProps}
    >
      <input
        className={classes.input}
        ref={ref}
        id={id}
        type="checkbox"
        onChange={handleChange}
        aria-checked={
          indeterminate ? "mixed" : rest.checked || rest.defaultChecked
        }
        {...rest}
      />
      <label className={classes.label} htmlFor={id} {...labelProps}>
        {label}
      </label>
    </div>
  );
};

export default forwardRef<HTMLInputElement, CheckboxProps>(Checkbox);
